parameters.jsCode:
const body = $input.first().json.body;
const required = ['patient_id', 'chief_complaint', 'provider_name'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
return [{ json: { valid: true, patientId: body.patient_id.trim(), patientAge: parseInt(body.patient_age)||null, patientSex: body.patient_sex||'', providerName: body.provider_name.trim(), appointmentType: body.appointment_type||'general', chiefComplaint: body.chief_complaint.trim().slice(0,1000), symptomsDescription: (body.symptoms_description||'').slice(0,2000), symptomDuration: body.symptom_duration||'', symptomSeverity: body.symptom_severity||'', currentMedications: (body.current_medications||'').slice(0,800), allergies: body.allergies||'', relevantHistory: (body.relevant_history||'').slice(0,1000), recentLabsOrTests: (body.recent_labs_or_tests||'').slice(0,600), patientConcerns: (body.patient_concerns||'').slice(0,600), insuranceNotes: body.insurance_notes||'', flagForUrgent: body.flag_for_urgent===true||body.flag_for_urgent==='true', submittedAt: new Date().toISOString() } }];

values.content:
Summarize this patient intake for the provider.

Patient ID: {{ $json.patientId }}
Age: {{ $json.patientAge || 'not provided' }} | Sex: {{ $json.patientSex || 'not provided' }}
Provider: {{ $json.providerName }}
Appointment type: {{ $json.appointmentType }}
Flagged urgent: {{ $json.flagForUrgent }}

Chief complaint: {{ $json.chiefComplaint }}
Symptoms: {{ $json.symptomsDescription || 'not provided' }}
Duration: {{ $json.symptomDuration || 'not specified' }}
Severity: {{ $json.symptomSeverity || 'not specified' }}

Medications: {{ $json.currentMedications || 'none listed' }}
Allergies: {{ $json.allergies || 'none listed' }}
Relevant history: {{ $json.relevantHistory || 'none provided' }}
Recent labs/tests: {{ $json.recentLabsOrTests || 'none provided' }}
Patient concerns: {{ $json.patientConcerns || 'none noted' }}

Return this JSON:
{
  "visit_summary": "2-3 sentence overview in clinical language",
  "chief_complaint_formatted": "clean clinical statement",
  "symptom_summary": [{ "symptom": "name", "duration": "how long", "severity": "descriptor", "character": "additional detail" }],
  "active_medications": ["medication list"],
  "allergy_summary": "formatted allergy statement or NKDA",
  "relevant_history_summary": "brief summary",
  "patient_concerns": ["what patient wants addressed"],
  "documentation_gaps": ["missing information typically collected for this complaint"],
  "urgency_flags": ["anything warranting prompt attention — empty if nothing concerning"],
  "suggested_review_items": ["items provider may want to verify — NOT diagnoses, just documentation prompts"]
}

