const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let summary;
try { summary = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
summary._intake = { patientId: input.patientId, patientAge: input.patientAge, patientSex: input.patientSex, providerName: input.providerName, appointmentType: input.appointmentType, flagForUrgent: input.flagForUrgent, submittedAt: input.submittedAt };
return [{ json: summary }];

const s = $input.first().json;
const intake = s._intake;
function esc(t) { return String(t||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const hasUrgency = (s.urgency_flags||[]).length > 0 || intake.flagForUrgent;
const symptomRows = (s.symptom_summary||[]).map(sym => `<tr style="border-bottom:1px solid #f0f0f0"><td style="padding:7px 12px;font-size:14px;font-weight:600">${esc(sym.symptom)}</td><td style="padding:7px 12px;font-size:13px;color:#6b7280">${esc(sym.duration||'?')}</td><td style="padding:7px 12px;font-size:13px;color:#6b7280">${esc(sym.severity||'?')}</td><td style="padding:7px 12px;font-size:13px;color:#6b7280">${esc(sym.character||'')}</td></tr>`).join('');
const listBlock = (items, color) => (items||[]).length ? `<ul style="padding-left:18px;margin:0">${(items||[]).map(i=>`<li style="font-size:13px;margin-bottom:5px;color:${color||'#374151'};line-height:1.5">${esc(i)}</li>`).join('')}</ul>` : '<div style="font-size:13px;color:#9ca3af">None</div>';
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f5f5f3;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111"><div style="max-width:680px;margin:0 auto"><div style="background:${hasUrgency?'#7f1d1d':'#1e3a5f'};color:#fff;padding:18px 26px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:${hasUrgency?'#fca5a5':'#93b4d4'};margin-bottom:5px">Pre-Visit Summary · ${esc(intake.appointmentType)}${hasUrgency?' · ⚠ URGENT':''}</div><div style="font-size:18px;font-weight:700">Patient ${esc(intake.patientId)}${intake.patientAge?' · '+intake.patientAge+'y':''}${intake.patientSex?' · '+esc(intake.patientSex):''}</div><div style="font-size:13px;color:${hasUrgency?'#fca5a5':'#93b4d4'};margin-top:3px">Provider: ${esc(intake.providerName)} · ${esc(intake.submittedAt.split('T')[0])}</div></div>${(s.urgency_flags||[]).length?`<div style="background:#fef2f2;padding:14px 26px;border:1px solid #fecaca;border-top:none"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:7px">⚠ Urgency flags</div>${(s.urgency_flags||[]).map(f=>`<div style="font-size:14px;color:#7f1d1d;padding:3px 0;font-weight:500">${esc(f)}</div>`).join('')}</div>`:''}<div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:none"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Chief complaint</div><div style="font-size:16px;font-weight:600;color:#111;margin-bottom:10px">${esc(s.chief_complaint_formatted)}</div><p style="font-size:14px;line-height:1.7;color:#374151;margin:0">${esc(s.visit_summary)}</p></div>${symptomRows?`<div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Symptoms</div><table style="width:100%;border-collapse:collapse"><thead><tr style="font-size:11px;text-transform:uppercase;color:#9ca3af"><th style="padding:6px 12px;text-align:left">Symptom</th><th style="padding:6px 12px;text-align:left">Duration</th><th style="padding:6px 12px;text-align:left">Severity</th><th style="padding:6px 12px;text-align:left">Character</th></tr></thead><tbody>${symptomRows}</tbody></table></div>`:''}<div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Medications</div>${listBlock(s.active_medications,'#374151')}</div><div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Allergies</div><div style="font-size:14px;color:#374151">${esc(s.allergy_summary||'Not documented')}</div></div></div></div><div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Relevant history</div><div style="font-size:14px;color:#374151;line-height:1.65">${esc(s.relevant_history_summary)}</div></div>${(s.patient_concerns||[]).length?`<div style="background:#eff6ff;padding:14px 26px;border:1px solid #bfdbfe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:6px">Patient concerns</div>${listBlock(s.patient_concerns,'#1e40af')}</div>`:''  }${(s.documentation_gaps||[]).length?`<div style="background:#fffbeb;padding:12px 26px;border:1px solid #fde68a"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:5px">Documentation gaps</div>${listBlock(s.documentation_gaps,'#78350f')}</div>`:''  }${(s.suggested_review_items||[]).length?`<div style="background:#f8f8f8;padding:12px 26px;border:1px solid #e5e7eb"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px">Provider review items</div>${listBlock(s.suggested_review_items,'#374151')}</div>`:''  }<div style="background:#1e3a5f;color:#4a7fa5;font-size:10px;padding:10px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Documentation aid only · Not a diagnostic tool · ${esc(intake.submittedAt.split('T')[0])}</div></div></body></html>`;
return [{ json: { html, patientId: intake.patientId, providerName: intake.providerName, hasUrgency, summary: s } }];
